{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "url": "/ds_salaries.csv",
    "format": {"type": "csv"}
  },
"vconcat": [
    {
      "title": "平均年薪趋势 (按经验级别)",
      "width": 600,
      "height": 300,
      "mark": {
        "type": "line",
        "point": true,
        "tooltip": true
      },
      "encoding": {
        "x": {
          "field": "work_year",
          "type": "ordinal",
          "title": "工作年份"
        },
        "y": {
          "field": "salary_in_usd",
          "type": "quantitative",
          "aggregate": "mean",
          "title": "平均年薪 (USD)"
        },
        "color": {
          "field": "experience_level",
          "type": "nominal",
          "title": "经验级别",
          "scale": {
            "domain": ["EN", "MI", "SE", "EX"],
            "range": ["#675193", "#ca8861", "#dc2626", "#0c46a0"]
          },
          "legend": {
