            "tickCount": 4,
            "values": [0, 50, 100]
          }
        },
        "y": {
          "field": "salary_in_usd",
          "type": "quantitative",
          "title": "年薪 (USD)",
          "scale": {"domain": [0, 300000]}
        },
        "color": {
          "condition": {
            "param": "brush",
            "field": "company_size",
            "type": "nominal",
            "title": "公司规模",
            "scale": {
              "domain": ["S", "M", "L"],
              "range": ["#ff6b6b", "#4ecdc4", "#556cd6"]
            },
            "legend": {
              "title": "公司规模",
              "labelExpr": "{'S':'小型','M':'中型','L':'大型'}[datum.value]"
            }
          },
