          "mark": "rule",
          "transform": [{"filter": {"selection": "year_brush"}}],
          "encoding": {"color": {"value": "gray"}}
        }
      ]
    },
    {
      "title": "多维度分析",
      "width": "container",
      "height": 100,
      "params": [
        {
          "name": "year_brush",
          "select": {"type": "interval", "encodings": ["x"]}
        }
      ],
      "mark": "bar",
      "encoding": {
        "x": {
          "field": "work_year",
          "type": "ordinal",
          "title": "年份"
        },
        "y": {
          "field": "salary_in_usd",
          "aggregate": "mean",
          "type": "quantitative",
          "title": "平均薪资 (USD)"
        },
        "color": {
          "field": "experience_level",
          "type": "nominal",
          "scale": {
            "domain": ["EN", "MI", "SE", "EX"],
            "range": ["#1f77b4", "#ff7f0e", "#2ca02c", "#d62728"]
          }
        },
        "tooltip": [
          {"field": "work_year", "title": "年份"},
          {"field": "experience_level", "title": "经验级别"},
          {"field": "salary_in_usd", "aggregate": "mean", "title": "平均薪资", "format": "$,"}
        ]
      }
    }
  ],
  "resolve": {"scale": {"x": "shared"}},
  "params": [
    {
      "name": "emp_type",
      "select": {
        "type": "point",
        "fields": ["employment_type"],
        "bind": {
          "input": "select",
          "options": [null, "FT", "PT", "CT", "FL"],
          "name": "雇佣类型: "
        }
      }
    },
    {
      "name": "company_size",
      "select": {
        "type": "point",
        "fields": ["company_size"],
        "bind": {
          "input": "radio",
          "options": [null, "S", "M", "L"],
          "name": "公司规模: "
        }
      }
    }
  ],
  "transform": [
    {
      "filter": {
        "or": [
          {"selection": "emp_type"},
          {"not": {"selection": "emp_type"}}
        ]
      }
    },
    {
      "filter": {
        "or": [
          {"selection": "company_size"},
          {"not": {"selection": "company_size"}}
        ]
      }
    }
  ],
  "config": {
    "view": {"stroke": "transparent"},
    "legend": {"orient": "top"}
  }
}

