  "data": {
    "url": "/ds_salaries.csv",
    "format": {"type": "csv"}
  },
  "vconcat": [
    {
      "title": "2020至2023年数据科学岗位平均薪资趋势",
      "width": 600,
      "height": 400,
      "mark": "line",
      "encoding": {
        "x": {
          "field": "work_year",
          "type": "ordinal",
          "title": "年份"
        },
        "y": {
          "aggregate": "mean",
          "field": "salary_in_usd",
          "type": "quantitative",
          "title": "平均年薪 (USD)"
        },
        "color": {
          "field": "job_title",
          "type": "nominal",
          "title": "职位",
          "legend": {
            "title": "职位"
          }
        },
        "tooltip": [
          {"field": "work_year", "title": "年份"},
          {"field": "job_title", "title": "职位"},
          {"aggregate": "mean", "field": "salary_in_usd", "title": "平均年薪", "format": "$,.0f"}
        ]
      }
    },

  ]
}

{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "url": "/ds_salaries.csv",
    "format": {"type": "csv"}
  },
  "vconcat": [
    {
      "title": "2020至2023年数据科学岗位平均薪资趋势",
      "width": 600,
      "height": 400,
      "mark": "line",
      "encoding": {
        "x": {
          "field": "work_year",
          "type": "ordinal",
          "title": "年份"
        },
        "y": {
          "aggregate": "mean",
          "field": "salary_in_usd",
          "type": "quantitative",
          "title": "平均年薪 (USD)"
        },
        "color": {
          "field": "job_title",
          "type": "nominal",
          "title": "职位",
          "legend": {
            "title": "职位"
          }
        },
        "tooltip": [
          {"field": "work_year", "title": "年份"},
          {"field": "job_title", "title": "职位"},
          {"aggregate": "mean", "field": "salary_in_usd", "title": "平均年薪", "format": "$,.0f"}
        ]
      }
    },
    {
      "title": "薪资趋势与经验级别 (USD)",
      "width": "container",
      "height": 300,
      "layer": [
