  "data": {"url": "your_data_source.csv"},
  "width": "container",
  "height": 500,
  "title": "薪资分析 (按经验级别与雇佣类型)",
  "params": [
    {
      "name": "year_range",
      "value": [2020, 2023],
      "bind": {
        "input": "range",
        "min": 2020,
        "max": 2023,
        "step": 1,
        "name": "年份范围:"
      }
    },
    {
      "name": "company_size",
      "select": {
        "type": "point",
        "fields": ["company_size"],
        "bind": {
          "input": "select",
          "options": [null, "S", "M", "L"],
          "name": "公司规模:"
        }
      }
    },
    {
      "name": "remote_filter",
      "select": {
        "type": "point",
        "fields": ["remote_ratio"],
        "bind": {
          "input": "select",
          "options": [null, 0, 50, 100],
          "labels": ["全部", "无远程", "部分远程", "全远程"],
          "name": "远程比例:"
        }
      }
    }
  ],
  "transform": [
    {"filter": "datum.work_year >= year_range[0] && datum.work_year <= year_range[1]"},
    {
      "filter": {
        "or": [
          {"selection": "company_size"},
          {"not": {"selection": "company_size"}}
        ]
      }
    },
    {
      "filter": {
        "or": [
          {"selection": "remote_filter"},
          {"not": {"selection": "remote_filter"}}
        ]
      }
    }
  ],
  "layer": [
    {
      "mark": {
        "type": "point",
        "filled": true,
        "size": 100,
        "opacity": 0.7
      },
      "encoding": {
        "x": {
          "field": "work_year",
          "type": "ordinal",
          "title": "工作年份"
        },
        "y": {
          "field": "salary_in_usd",
          "type": "quantitative",
          "aggregate": "median",
          "title": "薪资中位数 (USD)"
        },
        "color": {
          "field": "experience_level",
          "type": "nominal",
          "title": "经验级别",
          "scale": {
            "domain": ["EN", "MI", "SE", "EX"],
            "range": ["#66c2a5", "#fc8d62", "#8da0cb", "#e78ac3"]
          },
          "legend": {
            "title": "经验: EN=入门, MI=中级, SE=高级, EX=专家"
          }
        },
        "shape": {
          "field": "employment_type",
          "type": "nominal",
          "title": "雇佣类型",
          "scale": {
            "domain": ["FT", "PT", "CT", "FL"],
            "range": ["circle", "square", "diamond", "triangle-up"]
          },
          "legend": {
            "title": "类型: FT=全职, PT=兼职, CT=合同, FL=自由职业"
          }
        },
        "tooltip": [
          {"field": "work_year", "title": "年份"},
          {"field": "experience_level", "title": "经验级别"},
          {"field": "employment_type", "title": "雇佣类型"},
          {"field": "salary_in_usd", "aggregate": "median", "title": "薪资中位数", "format": "$,"},
          {"field": "remote_ratio", "title": "远程比例"},
          {"field": "company_size", "title": "公司规模"}
        ]
      }
    },
    {
      "mark": {
        "type": "line",
        "strokeWidth": 2
      },
      "encoding": {
        "x": {"field": "work_year", "type": "ordinal"},
        "y": {
          "field": "salary_in_usd",
          "aggregate": "median",
          "type": "quantitative"
        },
        "color": {"field": "experience_level", "type": "nominal"},
        "detail": {"field": "experience_level", "type": "nominal"}
      }
    },
    {
      "mark": {
        "type": "errorband",
        "extent": "iqr",
        "opacity": 0.3
      },
      "encoding": {
        "x": {"field": "work_year", "type": "ordinal"},
        "y": {
          "field": "salary_in_usd",
          "type": "quantitative",
          "title": "薪资中位数 (USD)"
        },
        "color": {"field": "experience_level", "type": "nominal"}
      }
    }
  ],
  "config": {
    "legend": {
      "orient": "top",
      "columns": 2
    },
    "axis": {
      "labelFontSize": 12,
      "titleFontSize": 14
    }
  }
}

