{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "description": "薪资数据分析仪表板",
  "data": {"url": "your_data_source.csv"},
  "width": "container",
  "height": 500,
  "title": "薪资分析 (按经验级别与雇佣类型)",
  "params": [
    {
      "name": "year_range",
      "value": [2020, 2023],
      "bind": {
        "input": "range",
        "min": 2020,
        "max": 2023,
        "step": 1,
        "name": "年份范围:"
      }
    },
    {
      "name": "company_size",
      "select": {
        "type": "point",
        "fields": ["company_size"],
        "bind": {
          "input": "select",
          "options": [null, "S", "M", "L"],
          "name": "公司规模:"
        }
      }
    },
    {
      "name": "remote_filter",
      "select": {
        "type": "point",
        "fields": ["remote_ratio"],
        "bind": {
          "input": "select",
          "options": [null, 0, 50, 100],
          "labels": ["全部", "无远程", "部分远程", "全远程"],
          "name": "远程比例:"
        }
      }
    }
  ],
  "transform": [
    {"filter": "datum.work_year >= year_range[0] && datum.work_year <= year_range[1]"},
    {
      "filter": {
        "or": [
          {"selection": "company_size"},
          {"not": {"selection": "company_size"}}
        ]
      }
    },
    {
      "filter": {
        "or": [
          {"selection": "remote_filter"},
          {"not": {"selection": "remote_filter"}}
        ]
      }
    }
  ],
